CREATE TYPE "Role" AS ENUM ('WORKER', 'ASSESSOR', 'REVIEWER', 'ADMIN');
CREATE TYPE "AssessmentStatus" AS ENUM ('DRAFT', 'IN_PROGRESS', 'AWAITING_REVIEW', 'APPROVED', 'RETURNED');
CREATE TABLE "User" ("id" TEXT NOT NULL, "name" TEXT NOT NULL, "role" "Role" NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "User_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Candidate" ("id" TEXT NOT NULL, "name" TEXT NOT NULL, "phone" TEXT, "language" TEXT NOT NULL DEFAULT 'English', "yearsExperience" DOUBLE PRECISION NOT NULL, "tasks" TEXT[] NOT NULL, "consent" BOOLEAN NOT NULL DEFAULT false, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "Candidate_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ContentSet" ("id" TEXT NOT NULL, "name" TEXT NOT NULL, "version" TEXT NOT NULL, "source" TEXT NOT NULL, "status" TEXT NOT NULL DEFAULT 'DEMO', "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "ContentSet_pkey" PRIMARY KEY ("id"));
CREATE TABLE "QualificationPack" ("id" TEXT NOT NULL, "contentSetId" TEXT NOT NULL, "title" TEXT NOT NULL, "demo" BOOLEAN NOT NULL DEFAULT true, CONSTRAINT "QualificationPack_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Standard" ("id" TEXT NOT NULL, "packId" TEXT NOT NULL, "code" TEXT NOT NULL, "title" TEXT NOT NULL, "criteria" TEXT[] NOT NULL, "demo" BOOLEAN NOT NULL DEFAULT true, CONSTRAINT "Standard_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Assessment" ("id" TEXT NOT NULL, "candidateId" TEXT NOT NULL, "assessorId" TEXT, "status" "AssessmentStatus" NOT NULL DEFAULT 'DRAFT', "scores" JSONB NOT NULL DEFAULT '{}', "draftResult" TEXT, "humanDecision" TEXT, "rubricVersion" TEXT NOT NULL DEFAULT 'demo-1', "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Assessment_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Evidence" ("id" TEXT NOT NULL, "assessmentId" TEXT NOT NULL, "kind" TEXT NOT NULL, "label" TEXT NOT NULL, "sha256" TEXT, "submittedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "reviewStatus" TEXT NOT NULL DEFAULT 'PENDING', CONSTRAINT "Evidence_pkey" PRIMARY KEY ("id"));
CREATE TABLE "AuditEvent" ("id" TEXT NOT NULL, "actor" TEXT NOT NULL, "action" TEXT NOT NULL, "entityType" TEXT NOT NULL, "entityId" TEXT NOT NULL, "detail" JSONB NOT NULL DEFAULT '{}', "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "AuditEvent_pkey" PRIMARY KEY ("id"));
CREATE TABLE "SignOff" ("id" TEXT NOT NULL, "assessmentId" TEXT NOT NULL, "reviewer" TEXT NOT NULL, "decision" TEXT NOT NULL, "reason" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "SignOff_pkey" PRIMARY KEY ("id"));
ALTER TABLE "QualificationPack" ADD CONSTRAINT "QualificationPack_contentSetId_fkey" FOREIGN KEY ("contentSetId") REFERENCES "ContentSet"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "Standard" ADD CONSTRAINT "Standard_packId_fkey" FOREIGN KEY ("packId") REFERENCES "QualificationPack"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "Assessment" ADD CONSTRAINT "Assessment_candidateId_fkey" FOREIGN KEY ("candidateId") REFERENCES "Candidate"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "Assessment" ADD CONSTRAINT "Assessment_assessorId_fkey" FOREIGN KEY ("assessorId") REFERENCES "User"("id") ON DELETE SET NULL ON UPDATE CASCADE;
